const $=id=>document.getElementById(id);const KEY='ritmo-tasks-v1';const today=new Date();const dateOffset=n=>{const d=new Date();d.setDate(d.getDate()+n);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`};
const samples=[['Planificar la semana','Personal','high','pending',1],['Leer 20 páginas','Aprendizaje','medium','progress',0],['Preparar propuesta de proyecto','Trabajo','high','progress',3],['Salir a caminar','Bienestar','low','done',0],['Organizar el escritorio','Personal','low','pending',2]].map(([title,category,priority,status,n])=>({id:crypto.randomUUID(),title,category,priority,status,due:dateOffset(n)}));let tasks;try{const saved=localStorage.getItem(KEY);tasks=saved?JSON.parse(saved):samples;if(!Array.isArray(tasks))tasks=samples}catch{tasks=samples}let filter='all',editing=null;const labels={pending:'Pendiente',progress:'En progreso',done:'Completada'},priorities={high:'Alta',medium:'Media',low:'Baja'};const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
$('date').textContent=new Intl.DateTimeFormat('es',{weekday:'long',day:'numeric',month:'long'}).format(today);let timer;function toast(message){$('toast').textContent=message;$('toast').classList.add('show');clearTimeout(timer);timer=setTimeout(()=>$('toast').classList.remove('show'),2500)}function save(){try{localStorage.setItem(KEY,JSON.stringify(tasks))}catch{toast('No se pudo guardar en este navegador.')}render()}
function render(){const done=tasks.filter(t=>t.status==='done').length;$('total').textContent=tasks.length;$('progress').textContent=tasks.filter(t=>t.status==='progress').length;$('completed').textContent=done;$('percent').textContent=tasks.length?`${Math.round(done/tasks.length*100)}% de tus tareas completadas`:'Tu próximo paso empieza aquí';$('navCount').textContent=tasks.length;$('listCount').textContent=tasks.length;const query=$('search').value.toLocaleLowerCase();const list=tasks.filter(t=>(filter==='all'||t.status===filter)&&`${t.title} ${t.category}`.toLocaleLowerCase().includes(query));$('tasks').innerHTML=list.length?list.map(t=>`<article class="task ${t.status==='done'?'done':''}" data-id="${esc(t.id)}"><div class="task-name"><button class="check ${t.status==='done'?'checked':''}" data-action="toggle" aria-label="${t.status==='done'?'Marcar como pendiente':'Completar tarea'}: ${esc(t.title)}">${t.status==='done'?'✓':''}</button><div><span class="task-title">${esc(t.title)}</span><span class="category">${esc(t.category||'Sin categoría')}</span></div></div><select class="status-select status-${esc(t.status)}" aria-label="Estado de ${esc(t.title)}">${Object.entries(labels).map(([v,l])=>`<option value="${v}" ${t.status===v?'selected':''}>${l}</option>`).join('')}</select><span class="priority ${esc(t.priority)}"><i></i>${priorities[t.priority]||'Media'}</span><span class="due">${t.due?new Intl.DateTimeFormat('es',{day:'numeric',month:'short'}).format(new Date(t.due+'T12:00:00')):'Sin fecha'}</span><div class="actions"><button data-action="edit" aria-label="Editar ${esc(t.title)}" title="Editar">✎</button><button data-action="delete" aria-label="Eliminar ${esc(t.title)}" title="Eliminar">×</button></div></article>`).join(''):'<div class="empty"><strong>No hay tareas aquí.</strong>Añade una tarea o cambia los filtros para empezar.</div>';$('results').textContent=`${list.length} de ${tasks.length} tareas`;document.querySelectorAll('[data-filter]').forEach(b=>b.classList.toggle('selected',b.dataset.filter===filter));$('doneNav').classList.toggle('active',filter==='done');$('allNav').classList.toggle('active',filter!=='done')}
function openForm(task){editing=task?.id??null;$('form').reset();$('dialogTitle').textContent=task?'Editar tarea':'Nueva tarea';if(task)for(const key of ['title','category','priority','due','status'])$(key).value=task[key]||'';$('dialog').showModal();$('title').focus()}
$('newTask').onclick=()=>openForm();$('close').onclick=()=>$('dialog').close();$('dialog').addEventListener('click',e=>{if(e.target===$('dialog')){const r=$('dialog').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('dialog').close()}});$('form').onsubmit=e=>{e.preventDefault();const title=$('title').value.trim();if(!title){$('title').setCustomValidity('Escribe un nombre para la tarea.');$('title').reportValidity();return}const task={id:editing||crypto.randomUUID(),title,category:$('category').value.trim(),priority:$('priority').value,due:$('due').value,status:$('status').value};if(editing)tasks=tasks.map(t=>t.id===editing?task:t);else tasks.unshift(task);save();$('dialog').close();toast(editing?'Tarea actualizada':'Tarea añadida')};$('title').oninput=()=>$('title').setCustomValidity('');$('search').oninput=render;document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;render()});$('allNav').onclick=()=>{filter='all';render()};$('doneNav').onclick=()=>{filter='done';render()};$('tasks').onclick=e=>{const button=e.target.closest('[data-action]');if(!button)return;const task=tasks.find(t=>t.id===button.closest('[data-id]').dataset.id);if(button.dataset.action==='edit')return openForm(task);if(button.dataset.action==='delete'){if(!confirm(`¿Eliminar «${task.title}»?`))return;tasks=tasks.filter(t=>t.id!==task.id);toast('Tarea eliminada')}else task.status=task.status==='done'?'pending':'done';save()};$('tasks').onchange=e=>{if(e.target.matches('select')){const task=tasks.find(t=>t.id===e.target.closest('[data-id]').dataset.id);task.status=e.target.value;save()}};render();
